        action('Place', {}),
        action('Pay', { amount: t.int.check([10, 20]) }),
        on('Place', ($) => [require($.status === $.Draft, 'not-draft'), require($.items > 0, 'empty-order'), set('status', $.Placed)]),
        on('Pay', ($) => [require($.status === $.Placed, 'not-placed'), emit('charge', { amount: $.amount })]),
