import { test } from 'node:test';
import assert from 'node:assert/strict';
import create from '../build/host.gen.ts';

test('initial state', async () => {
  const h = await create();
  assert.deepEqual(await h.run(), { status: 'idle', task0: 'idle', task1: 'idle' });
  assert.deepEqual(await h.worker('worker0'), { status: 'idle' });
  assert.equal(await h.worker('nope'), null);
  assert.equal((await h.workDone('worker0')).ok, false);
  assert.equal((await h.cancel()).ok, false);
});

test('start sends Assign to each worker', async () => {
  const h = await create();
  assert.deepEqual(await h.start(), { ok: true });
  assert.equal((await h.start()).ok, false);
  assert.deepEqual(await h.run(), { status: 'running', task0: 'assigned', task1: 'assigned' });
  const msgs = (await h.inFlight()).map((m) => ({ from: m.from, to: m.to, action: m.action, data: m.data }));
  assert.deepEqual(msgs.sort((a, b) => a.to.localeCompare(b.to)), [
    { from: 'run', to: 'worker0', action: 'Assign', data: {} },
    { from: 'run', to: 'worker1', action: 'Assign', data: {} },
  ]);
  assert.equal((await h.workDone('worker0')).ok, false);
  await h.deliverAll();
  assert.deepEqual(await h.worker('worker0'), { status: 'busy' });
});

test('both complete', async () => {
  const h = await create();
  await h.start(); await h.deliverAll();
  assert.deepEqual(await h.workDone('worker0'), { ok: true });
  const [m] = await h.inFlight();
  assert.deepEqual({ from: m.from, to: m.to, action: m.action, data: m.data },
    { from: 'worker0', to: 'run', action: 'Report', data: { task: 0, outcome: 'completed' } });
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'running', task0: 'completed', task1: 'assigned' });
  await h.workDone('worker1'); await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'completed', task0: 'completed', task1: 'completed' });
  assert.deepEqual(await h.worker('worker1'), { status: 'idle' });
});

test('one fails', async () => {
  const h = await create();
  await h.start(); await h.deliverAll();
  await h.workFailed('worker1'); await h.deliverAll();
  assert.equal((await h.run()).status, 'running');
  await h.workDone('worker0'); await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'failed', task0: 'completed', task1: 'failed' });
});

test('cancel races a completion', async () => {
  const h = await create();
  await h.start(); await h.deliverAll();
  await h.workDone('worker0'); // report in flight, task0 still assigned at the run
  assert.deepEqual(await h.cancel(), { ok: true });
  assert.equal((await h.cancel()).ok, false);
  const aborts = (await h.inFlight()).filter((m) => m.action === 'Abort');
  assert.deepEqual(aborts.map((m) => m.to).sort(), ['worker0', 'worker1']);
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'cancelled', task0: 'completed', task1: 'cancelled' });
  assert.deepEqual(await h.worker('worker0'), { status: 'idle' });
});

test('cancel after both report-in-flight is ignored by idle workers', async () => {
  const h = await create();
  await h.start(); await h.deliverAll();
  await h.workDone('worker0'); await h.deliverAll();
  await h.cancel();
  const aborts = (await h.inFlight()).filter((m) => m.action === 'Abort');
  assert.deepEqual(aborts.map((m) => m.to), ['worker1']);
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'cancelled', task0: 'completed', task1: 'cancelled' });
});

test('cancel before assign arrives', async () => {
  const h = await create();
  await h.start();
  await h.cancel();
  // deliver aborts first: workers idle, aborts ignored; then assigns make them busy
  for (const m of await h.inFlight()) if (m.action === 'Abort') await h.deliver(m.id);
  await h.deliverAll();
  assert.equal((await h.run()).status, 'cancelling');
  await h.workFailed('worker0'); await h.workDone('worker1'); await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'failed', task0: 'failed', task1: 'completed' });
});

