test('both complete', async () => {
  const h = await create();
  await h.start(); await h.deliverAll();
  assert.deepEqual(await h.workDone('worker0', 1), { ok: true });
  const [m] = await h.inFlight();
  assert.deepEqual({ from: m.from, to: m.to, action: m.action, data: m.data },
    { from: 'worker0', to: 'run', action: 'Report', data: { task: 0, outcome: 'completed' } });
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'running', task0: 'completed', task1: 'assigned', retried0: false, retried1: false, processed: 0 });
  await h.workDone('worker1', 1); await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'completed', task0: 'completed', task1: 'completed', retried0: false, retried1: false, processed: 0 });
  assert.deepEqual(await h.worker('worker1'), { status: 'idle' });
});

test('a first failure is retried, a second is recorded', async () => {
  const h = await create();
  await h.start(); await h.deliverAll();
  await h.workFailed('worker1'); await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'running', task0: 'assigned', task1: 'assigned', retried0: false, retried1: true, processed: 0 });
  assert.deepEqual(await h.worker('worker1'), { status: 'busy' });
  await h.workDone('worker0', 1); await h.deliverAll();
  await h.workFailed('worker1'); await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'failed', task0: 'completed', task1: 'failed', retried0: false, retried1: true, processed: 0 });
});

