  assert.deepEqual(re.map((x) => [x.from, x.to, x.action]), [['run', 'worker0', 'Assign']]);
  await h.deliverAll();
  await h.workDone('worker0', 1); await h.workDone('worker1', 1); await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'completed', task0: 'completed', task1: 'completed', retried0: true, retried1: false, processed: 0 });
});

